// Provenance: test/golang/StandardnessCheck_test.go `standardnessCheckTxHex`.
pub const STANDARDNESS_TX_HEX: &str = "";

pub fn decode_hex(hex: &str) -> Vec<u8> {
    let trimmed = hex.trim();
    assert!(
        trimmed.len() % 2 == 0,
        "hex string has odd length: {}",
        trimmed.len()
    );

    trimmed
        .as_bytes()
        .chunks_exact(2)
        .map(|pair| (hex_nibble(pair[0]) << 4) | hex_nibble(pair[1]))
        .collect()
}

fn hex_nibble(byte: u8) -> u8 {
    match byte {
        b'0'..=b'9' => byte - b'0',
        b'a'..=b'f' => byte - b'a' + 10,
        b'A'..=b'F' => byte - b'A' + 10,
        _ => panic!("invalid hex byte: {byte}"),
    }
}
